     * @return string Its markup, from filter-form.phtml.
     */
    private function renderFilterForm(FilterForm $filterForm, RenderPass $renderPass): string
    {
        $renderPass->open($filterForm);
        require __DIR__ . '/filter-form.phtml';

        return $renderPass->close();
    }

    /**
     * @param ProfilerLayout $profilerLayout The component; its template reads it.
     * @param RenderPass     $renderPass     The pass its template writes through.
     *
     * @throws UnknownComponent When a child has no template.
